{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2185-10-19 16:05:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be your doctor during this stay. You were admitted for rib pain, correct?"
    },
    {
      "turn_number": 2,
      "time": "2185-10-19 16:06:00",
      "speaker": "Patient",
      "text": "Yes, I lifted a heavy bag and now my left side hurts badly."
    },
    {
      "turn_number": 3,
      "time": "2185-10-19 16:07:00",
      "speaker": "Doctor",
      "text": "We reviewed your chest X-ray. No fracture, but the area is tender. We’ll treat it as musculoskeletal pain."
    },
    {
      "turn_number": 4,
      "time": "2185-10-19 16:08:00",
      "speaker": "Patient",
      "text": "Okay, but I also have terrible abdominal pain. It’s constant and worse lately."
    },
    {
      "turn_number": 5,
      "time": "2185-10-19 16:09:00",
      "speaker": "Doctor",
      "text": "I see you have a complex GI history. You're on a pain contract and taking morphine at home?"
    },
    {
      "turn_number": 6,
      "time": "2185-10-19 16:10:00",
      "speaker": "Patient",
      "text": "Yes, but it’s not enough. I need IV Dilaudid. I’ve had it before during admissions."
    },
    {
      "turn_number": 7,
      "time": "2185-10-19 16:11:00",
      "speaker": "Doctor",
      "text": "I’ve consulted pain management. Dilaudid can worsen your bowel motility, which is already very slow."
    },
    {
      "turn_number": 8,
      "time": "2185-10-19 16:12:00",
      "speaker": "Patient",
      "text": "But I need relief. Without it, I can’t function. I’ll leave if I don’t get it."
    },
    {
      "turn_number": 9,
      "time": "2185-10-19 16:13:00",
      "speaker": "Doctor",
      "text": "I understand you're in pain, but we can’t give IV Dilaudid. It could cause a bowel blockage."
    },
    {
      "turn_number": 10,
      "time": "2185-10-19 16:14:00",
      "speaker": "Patient",
      "text": "Then I’m leaving. I can’t stay here without proper pain control."
    },
    {
      "turn_number": 11,
      "time": "2185-10-19 16:15:00",
      "speaker": "Doctor",
      "text": "We’ll discharge you with your home meds and the Lidoderm patch for your rib. Are you safe to go home?"
    },
    {
      "turn_number": 12,
      "time": "2185-10-19 16:16:00",
      "speaker": "Patient",
      "text": "Fine. But I’m not okay. I’m going to kill myself when I get home."
    },
    {
      "turn_number": 13,
      "time": "2185-10-19 16:17:00",
      "speaker": "Doctor",
      "text": "I need to take that seriously. We’ll get Psychiatry to see you right away."
    },
    {
      "turn_number": 14,
      "time": "2185-10-19 17:30:00",
      "speaker": "Doctor",
      "text": "Psychiatry has evaluated you. They’re concerned and want to keep you for observation."
    },
    {
      "turn_number": 15,
      "time": "2185-10-19 17:31:00",
      "speaker": "Patient",
      "text": "I don’t want to be here if I can’t have Dilaudid. I pulled my femoral line. I thought I’d bleed to death."
    },
    {
      "turn_number": 16,
      "time": "2185-10-19 17:32:00",
      "speaker": "Doctor",
      "text": "We saw that. There was minimal bleeding, but it’s a serious act. You’re now on a 1:1 sitter for safety."
    },
    {
      "turn_number": 17,
      "time": "2185-10-20 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. How are you feeling today?"
    },
    {
      "turn_number": 18,
      "time": "2185-10-20 08:16:00",
      "speaker": "Patient",
      "text": "Still in pain. And I need my femoral line replaced. I can’t eat. I need TPN."
    },
    {
      "turn_number": 19,
      "time": "2185-10-20 08:17:00",
      "speaker": "Doctor",
      "text": "We’ve been watching. You’ve been seen eating and drinking. Nutrition did a calorie count."
    },
    {
      "turn_number": 20,
      "time": "2185-10-20 08:18:00",
      "speaker": "Patient",
      "text": "I can’t keep food down. I’m nauseous all the time. I need the line."
    },
    {
      "turn_number": 21,
      "time": "2185-10-20 08:19:00",
      "speaker": "Doctor",
      "text": "The count showed you’re taking in about 68% of calories and 29% of protein. It’s low, but not critical."
    },
    {
      "turn_number": 22,
      "time": "2185-10-20 08:20:00",
      "speaker": "Patient",
      "text": "But I can’t live like this. I need the line replaced. And I need IV pain meds."
    },
    {
      "turn_number": 23,
      "time": "2185-10-20 08:21:00",
      "speaker": "Doctor",
      "text": "Your GI doctor reviewed your case. He doesn’t feel the line is needed right now."
    },
    {
      "turn_number": 24,
      "time": "2185-10-20 08:22:00",
      "speaker": "Patient",
      "text": "Then I’ll just keep saying I want to die until someone listens."
    },
    {
      "turn_number": 25,
      "time": "2185-10-20 08:23:00",
      "speaker": "Doctor",
      "text": "We take your words seriously. That’s why you’re on a sitter and seeing Psychiatry daily."
    },
    {
      "turn_number": 26,
      "time": "2185-10-21 09:00:00",
      "speaker": "Doctor",
      "text": "We did an upper GI study with Gastrografin. The contrast reached your cecum in 45 minutes."
    },
    {
      "turn_number": 27,
      "time": "2185-10-21 09:01:00",
      "speaker": "Patient",
      "text": "So? I still can’t eat."
    },
    {
      "turn_number": 28,
      "time": "2185-10-21 09:02:00",
      "speaker": "Doctor",
      "text": "The study shows no blockage. Your bowel is moving things through, just slowly. It’s stable."
    },
    {
      "turn_number": 29,
      "time": "2185-10-21 09:03:00",
      "speaker": "Patient",
      "text": "But I need the femoral line. I have no other access."
    },
    {
      "turn_number": 30,
      "time": "2185-10-21 09:04:00",
      "speaker": "Doctor",
      "text": "We understand, but without a medical need, we can’t replace it. We can use oral or rectal meds."
    },
    {
      "turn_number": 31,
      "time": "2185-10-21 09:05:00",
      "speaker": "Patient",
      "text": "They don’t work. Only IV works. You’re not helping me."
    },
    {
      "turn_number": 32,
      "time": "2185-10-22 10:00:00",
      "speaker": "Doctor",
      "text": "You’ve had a few episodes where you arch your back and moan. Neurology thinks they may be pseudoseizures."
    },
    {
      "turn_number": 33,
      "time": "2185-10-22 10:01:00",
      "speaker": "Patient",
      "text": "They’re not fake. I’ve been evaluated. I have real seizures."
    },
    {
      "turn_number": 34,
      "time": "2185-10-22 10:02:00",
      "speaker": "Doctor",
      "text": "We’ll keep following with Neurology. But during the episodes, you respond to touch."
    },
    {
      "turn_number": 35,
      "time": "2185-10-22 10:03:00",
      "speaker": "Patient",
      "text": "I can’t control them. And I’m still in pain. Why won’t you give me Dilaudid?"
    },
    {
      "turn_number": 36,
      "time": "2185-10-22 10:04:00",
      "speaker": "Doctor",
      "text": "Because it could stop your bowels completely. You’ve had obstructions before. It’s too risky."
    },
    {
      "turn_number": 37,
      "time": "2185-10-23 08:30:00",
      "speaker": "Doctor",
      "text": "Your labs are stable. White count is low but not concerning. Kidney and liver function are okay."
    },
    {
      "turn_number": 38,
      "time": "2185-10-23 08:31:00",
      "speaker": "Patient",
      "text": "I still feel awful. And I’m not eating because I’m nauseous."
    },
    {
      "turn_number": 39,
      "time": "2185-10-23 08:32:00",
      "speaker": "Doctor",
      "text": "We’ve seen you eat meals. We believe you can maintain nutrition without the femoral line for now."
    },
    {
      "turn_number": 40,
      "time": "2185-10-23 08:33:00",
      "speaker": "Patient",
      "text": "You don’t believe me. I need IV meds and my line back."
    },
    {
      "turn_number": 41,
      "time": "2185-10-24 09:15:00",
      "speaker": "Doctor",
      "text": "Psychiatry says your suicidal thoughts have decreased. You haven’t mentioned self-harm today."
    },
    {
      "turn_number": 42,
      "time": "2185-10-24 09:16:00",
      "speaker": "Patient",
      "text": "I’m still in pain. But I guess I won’t say I want to die anymore."
    },
    {
      "turn_number": 43,
      "time": "2185-10-24 09:17:00",
      "speaker": "Doctor",
      "text": "We’re glad. And your pain seems at baseline. The Lidoderm patch is helping your rib."
    },
    {
      "turn_number": 44,
      "time": "2185-10-24 09:18:00",
      "speaker": "Patient",
      "text": "But my belly pain is still there. You’re not fixing it."
    },
    {
      "turn_number": 45,
      "time": "2185-10-24 09:19:00",
      "speaker": "Doctor",
      "text": "We’ve done all we can safely. No new blockage, no infection. We can’t give IV Dilaudid."
    },
    {
      "turn_number": 46,
      "time": "2185-10-25 08:00:00",
      "speaker": "Doctor",
      "text": "We’re discharging you today. You’re medically stable. Your mental state has improved."
    },
    {
      "turn_number": 47,
      "time": "2185-10-25 08:01:00",
      "speaker": "Patient",
      "text": "I still don’t feel better. But I’ll go."
    },
    {
      "turn_number": 48,
      "time": "2185-10-25 08:02:00",
      "speaker": "Doctor",
      "text": "You’ll go home with your regular meds. Morphine PR for pain, and we’ve adjusted your Lovenox dose."
    },
    {
      "turn_number": 49,
      "time": "2185-10-25 08:03:00",
      "speaker": "Patient",
      "text": "No IV access? No Dilaudid?"
    },
    {
      "turn_number": 50,
      "time": "2185-10-25 08:04:00",
      "speaker": "Doctor",
      "text": "No. But we’ve spoken with your GI and pain doctors. Follow up with them soon."
    },
    {
      "turn_number": 51,
      "time": "2185-10-25 08:05:00",
      "speaker": "Patient",
      "text": "Fine. I’ll call them."
    },
    {
      "turn_number": 52,
      "time": "2185-10-25 08:06:00",
      "speaker": "Doctor",
      "text": "And please reach out if you feel unsafe. You’re not alone."
    },
    {
      "turn_number": 53,
      "time": "2185-10-25 08:07:00",
      "speaker": "Patient",
      "text": "I know. I won’t do anything. I just want to feel heard."
    },
    {
      "turn_number": 54,
      "time": "2185-10-25 08:08:00",
      "speaker": "Doctor",
      "text": "We hear you. This is complex, and we’re coordinating with your team. Take care."
    },
    {
      "turn_number": 55,
      "time": "2185-10-25 08:09:00",
      "speaker": "Patient",
      "text": "Thank you for not giving up on me, even when I was angry."
    },
    {
      "turn_number": 56,
      "time": "2185-10-25 08:10:00",
      "speaker": "Doctor",
      "text": "Of course. Your safety is our priority. We’ll be here if you need us."
    },
    {
      "turn_number": 57,
      "time": "2185-10-25 08:11:00",
      "speaker": "Patient",
      "text": "I’ll follow up with my doctors. I promise."
    },
    {
      "turn_number": 58,
      "time": "2185-10-25 08:12:00",
      "speaker": "Doctor",
      "text": "That’s all we ask. You’re strong, and you’ve gotten through a tough time."
    },
    {
      "turn_number": 59,
      "time": "2185-10-25 08:13:00",
      "speaker": "Patient",
      "text": "I feel a little more hope today."
    },
    {
      "turn_number": 60,
      "time": "2185-10-25 08:14:00",
      "speaker": "Doctor",
      "text": "We’re glad. Take it one day at a time. You’re going home with a clear mind and safe plan."
    },
    {
      "turn_number": 61,
      "time": "2185-10-25 08:15:00",
      "speaker": "Patient",
      "text": "I’m ready to go home now."
    },
    {
      "turn_number": 62,
      "time": "2185-10-25 08:16:00",
      "speaker": "Doctor",
      "text": "We’ll get the discharge papers ready. Rest, stay hydrated, and call if anything changes."
    },
    {
      "turn_number": 63,
      "time": "2185-10-25 08:17:00",
      "speaker": "Patient",
      "text": "I will. Thank you."
    },
    {
      "turn_number": 64,
      "time": "2185-10-25 08:18:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care of yourself."
    },
    {
      "turn_number": 65,
      "time": "2185-10-25 08:19:00",
      "speaker": "Patient",
      "text": "I’ll try."
    },
    {
      "turn_number": 66,
      "time": "2185-10-25 08:20:00",
      "speaker": "Doctor",
      "text": "That’s all anyone can do. We believe in you."
    },
    {
      "turn_number": 67,
      "time": "2185-10-25 08:21:00",
      "speaker": "Patient",
      "text": "I appreciate that."
    }
  ],
  "summary": {
    "admission_start": "2185-10-19 16:02:00",
    "admission_end": "2185-10-25 15:57:00",
    "summary_paragraph": "A woman with a complex medical history including sclerosing mesenteritis, chronic gastrointestinal dysmotility, and depression was admitted for musculoskeletal rib pain. She developed suicidal ideation after being denied IV Dilaudid for chronic abdominal pain, leading to self-removal of her femoral line. She was placed on a 1:1 sitter and evaluated by psychiatry. Calorie counts and a Gastrografin study showed stable bowel function without obstruction, and she was deemed safe for oral nutrition. Despite ongoing demands for IV pain control and femoral line replacement, the medical team determined these were not medically indicated. Her suicidal ideation resolved over several days, and she was discharged home with her home medications and follow-up plans after being deemed medically and psychiatrically stable.",
    "problems": [
      "Unspecified episodic mood disorder",
      "Suicidal ideation",
      "Chest pain, unspecified",
      "Abdominal pain, unspecified site",
      "Other chronic pain",
      "Dyspepsia and other specified disorders of function of stomach",
      "Chronic hepatitis C without mention of hepatic coma",
      "Irritable bowel syndrome",
      "Personal history of venous thrombosis and embolism",
      "Other convulsions",
      "Major depressive affective disorder, recurrent episode, unspecified",
      "Migraine, unspecified, without mention of intractable migraine without mention of status migrainosus",
      "Unspecified acquired hypothyroidism",
      "Sicca syndrome",
      "Sclerosing mesenteritis",
      "Carrier or suspected carrier of Methicillin resistant Staphylococcus aureus",
      "Personal history of noncompliance with medical treatment, presenting hazards to health",
      "Do not resuscitate status"
    ]
  }
}
